effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Rampa "inferno" aproximada em 5 pontos: preto-azul-roxo-vermelho-amarelo-branco. */
vec3 rampaTermica(float t) {
    t = clamp(t, 0.0, 1.0);
    vec3 c;
    if (t < 0.2)      c = mix(vec3(0.0),              vec3(0.1, 0.0, 0.5),  t / 0.2);
    else if (t < 0.4) c = mix(vec3(0.1, 0.0, 0.5),    vec3(0.6, 0.0, 0.5),  (t - 0.2) / 0.2);
    else if (t < 0.6) c = mix(vec3(0.6, 0.0, 0.5),    vec3(1.0, 0.2, 0.0),  (t - 0.4) / 0.2);
    else if (t < 0.8) c = mix(vec3(1.0, 0.2, 0.0),    vec3(1.0, 0.85, 0.0), (t - 0.6) / 0.2);
    else              c = mix(vec3(1.0, 0.85, 0.0),   vec3(1.0),            (t - 0.8) / 0.2);
    return c;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // Temperatura é luma com contraste e viés aplicados.
    float T = luma(original.rgb);
    T = (T - 0.5) * contrast + 0.5 + bias;

    vec3 termica = rampaTermica(T);

    // Saturação da rampa: mistura entre o cinza perceptual da rampa e ela mesma.
    float cinzaDaRampa = luma(termica);
    termica = mix(vec3(cinzaDaRampa), termica, saturation);

    vec3 cor = mix(original.rgb, termica, strength);
    fragColor = vec4(cor, original.a);
}
